'use strict';
(() => {
  const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const norm=value=>String(value??'').normalize('NFC').replace(/[’‘]/g,"'").toLocaleLowerCase('fr').replace(/\s+([,.!?;:])/g,'$1').replace(/^[\s.!?]+|[\s.!?]+$/g,'').replace(/\s+/g,' ').trim();
  const labels={cloze:'Completar y conjugar',transform:'Transformar',order:'Reconstruir',choice:'Elegir con contexto',correct:'Revisar un error',production:'Producir y revisar'};
  const callbacks={render(){},play(){},toast(){},onMistake(){}};
  const state={active:false,level:'A1',type:'all',index:0,attempts:new Map()};
  const data=()=>window.ATELIER_EXAM_REVIEW_DATA||{};
  const exercises=()=>Array.isArray(data().exercises)?data().exercises:[];
  const filtered=()=>exercises().filter(x=>x.level===state.level&&(state.type==='all'||x.type===state.type));
  const current=()=>filtered()[Math.min(state.index,Math.max(0,filtered().length-1))];
  function attempt(item=current()) { if(!item)return {};if(!state.attempts.has(item.id))state.attempts.set(item.id,{draft:'',open:false,feedback:'',practiceChoice:null,tokens:[],practiceFeedback:'',rubric:[]});return state.attempts.get(item.id); }
  const btn=(action,text,attrs='',cls='er-button')=>`<button type="button" class="${cls}" data-exam-review-action="${action}" ${attrs}>${text}</button>`;
  const paragraphs=(value,cls='')=>String(value||'').split('\n').map(p=>`<p class="${cls}" lang="fr">${esc(p)}</p>`).join('');
  function refresh(focus) { callbacks.render();if(focus&&typeof document!=='undefined')document.getElementById(focus)?.focus({preventScroll:true}); }
  function sourceLinks(item) { const links=[...new Set(item?.sourceURLs||data().meta?.sourceURLs||[])].filter(u=>/^https:\/\//.test(u));return links.map((url,i)=>`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">France Éducation international${links.length>1?` · ${i+1}`:''} ↗</a>`).join(''); }
  function photo(v) { const p=v?.image,c=p?.crop;if(p?.src)return `<img class="er-photo er-direct-photo" src="${esc(p.src)}" alt="${esc(p.altFR||v.word)}" loading="lazy" decoding="async">`;if(!p?.sheet||!c)return '';const n=(v,fallback)=>Number.isFinite(Number(v))?Number(v):fallback;return `<span class="er-photo" role="img" aria-label="${esc(p.altFR||v.word)}" style="background-image:url('${esc(p.sheet)}');background-size:${n(c.width,300)}% ${n(c.height,300)}%;background-position:${n(c.x,0)}% ${n(c.y,0)}%"></span>`; }
  function libraryItem(id) { const lib=window.ATELIER_LIBRARY;const rows=Array.isArray(lib)?lib:Array.isArray(lib?.vocabulary)?lib.vocabulary:[];return rows.find(x=>x.id===id); }
  function vocabulary(item) {return `<aside class="er-vocabulary" aria-labelledby="er-vocabulary-heading"><div class="er-small-heading"><h3 id="er-vocabulary-heading">Léxico en imágenes</h3><span>De tus materiales</span></div><div class="er-vocabulary-grid">${(item.vocabularyTargets||[]).map(v=>{const original=libraryItem(v.id);return `<article class="er-word">${photo(v)}<div><strong lang="fr">${esc(v.word)}</strong><span>${esc(v.translationES)}</span>${original?.audio?btn('audio','Escuchar el ejemplo',`data-source-id="${esc(v.id)}"`,'er-text-button'):''}</div></article>`;}).join('')}</div><p class="er-photo-note">Fotografías generadas para tu biblioteca. El audio reproduce el ejemplo original de la palabra.</p></aside>`;}
  function givenMaterial(item){
    if(item.type==='order')return `<div class="er-given" role="group" aria-label="Bloques para ordenar"><p>Bloques disponibles · escribe la frase completa</p><div class="er-given-blocks" lang="fr">${(item.tokens||[]).map(t=>`<span>${esc(t)}</span>`).join('')}</div></div>`;
    if(item.type==='choice')return `<div class="er-given" role="group" aria-label="Opciones para tu respuesta"><p>Escribe la letra o el texto de tu elección.</p><ol class="er-given-choices" type="A" lang="fr">${(item.options||[]).map(t=>`<li>${esc(t)}</li>`).join('')}</ol></div>`;
    return '';
  }
  function practice(item,a) {
    if(item.type==='production')return `<div class="er-rubric"><h4>Revisa tu texto con estos criterios</h4>${(item.rubric||[]).map((r,i)=>`<label><input type="checkbox" data-exam-review-filter="rubric" data-index="${i}" ${a.rubric.includes(i)?'checked':''}><span>${esc(r)}</span></label>`).join('')}<p>La selección refleja tu autoevaluación. La corrección de una producción necesita valorar su sentido y su adecuación; no se calcula una nota automática.</p></div>`;
    if(item.type==='choice')return `<div class="er-practice"><h4>Vuelve a decidir con la explicación</h4><div class="er-options">${(item.options||[]).map((o,i)=>btn('choice',esc(o),`data-index="${i}" aria-pressed="${a.practiceChoice===i}"`,'er-option'+(a.practiceChoice===i?' is-selected':''))).join('')}</div>${btn('practice-check','Comparar esta elección','','er-button er-secondary')}</div>`;
    if(item.type==='order')return `<div class="er-practice"><h4>Reconstruye ahora la frase</h4><div class="er-built" aria-live="polite" lang="fr">${a.tokens.length?a.tokens.map((i,pos)=>btn('remove-token',esc(item.tokens[i]),`data-index="${pos}"`,'er-token er-token-chosen')).join(''):'Selecciona los bloques de abajo.'}</div><div class="er-token-bank">${(item.tokens||[]).map((t,i)=>btn('token',esc(t),`data-index="${i}" ${a.tokens.includes(i)?'disabled':''}`,'er-token')).join('')}</div><div class="er-actions">${btn('clear-tokens','Vaciar bloques','','er-text-button')}${btn('practice-check','Comparar la frase','','er-button er-secondary')}</div></div>`;
    return `<div class="er-practice"><h4>Otro intento a partir del patrón</h4><p>Tapa el modelo, repite la forma y vuelve a escribir la respuesta inicial con tus propias correcciones.</p>${btn('another','Tapar y volver a intentar','','er-button er-secondary')}</div>`;
  }
  function solution(item,a) { if(!a.open)return '';const alternatives=[...new Set((item.answers||[]).map(x=>x))];return `<section class="er-solution" id="er-solution" aria-labelledby="er-solution-title"><div class="er-solution-heading"><div><p class="er-kicker">02 · Compara y vuelve a practicar</p><h3 id="er-solution-title">${item.selfAssess?'Una respuesta posible':'Solución y explicación'}</h3></div>${btn('hide-solution','Tapar solución','','er-text-button')}</div><div class="er-model" lang="fr">${paragraphs(item.modelFR)}</div><p class="er-explanation">${esc(item.explanationES)}</p>${alternatives.length>1?`<details class="er-alternatives"><summary>Otras formas admitidas en este ejercicio</summary><ul>${alternatives.slice(1).map(s=>`<li lang="fr">${esc(s)}</li>`).join('')}</ul></details>`:''}${practice(item,a)}${a.practiceFeedback?`<p class="er-feedback" role="status">${esc(a.practiceFeedback)}</p>`:''}</section>`;}
  function render() {
    const list=filtered(),item=current(),profile=(data().levelProfiles||[]).find(x=>x.level===state.level),a=attempt(item);
    return `<div class="er-page"><nav class="er-top-links" aria-label="Ir a los verbos"><a href="#verbs">← Conjugaciones</a><a href="#verb-tips">Formación y patrones →</a></nav><header class="er-hero"><div><p class="er-kicker">Atelier de révision · A1–C2</p><h1>Del patrón<br><em>a la expresión.</em></h1><p>Conjuga, reformula y elige palabras con precisión. Piensa primero; la solución se convierte después en una práctica guiada.</p></div><div class="er-hero-mark" aria-hidden="true"><span>je</span><b>comprends</b><i>et je reformule.</i></div></header><div class="er-exam-note"><strong>Un repaso para preparar la comunicación.</strong><p>DELF y DALF evalúan comprensión y producción. No tienen una prueba independiente de gramática y vocabulario. Estos ejercicios originales preparan recursos lingüísticos; los niveles orientan tu repaso.</p><details><summary>Cómo se relaciona con el examen</summary><p>${esc(data().meta?.disclaimerES||'No es un examen oficial ni una certificación de nivel.')}</p><p>${esc(data().meta?.levelBasisES||'')}</p></details></div><section class="er-controls" aria-label="Elegir el repaso"><label>Nivel<select data-exam-review-filter="level">${(data().meta?.levels||['A1','A2','B1','B2','C1','C2']).map(l=>`<option ${l===state.level?'selected':''}>${esc(l)}</option>`).join('')}</select></label><label>Tipo de práctica<select data-exam-review-filter="type"><option value="all" ${state.type==='all'?'selected':''}>Todos los tipos</option>${Object.entries(labels).map(([k,v])=>`<option value="${k}" ${state.type===k?'selected':''}>${v}</option>`).join('')}</select></label><div class="er-level-profile"><strong>${esc(profile?.focusES||'Repaso a tu ritmo')}</strong><p>${esc(profile?.examRelationES||'')}</p></div></section>${item?`<section class="er-exercise" aria-labelledby="er-exercise-title"><div class="er-exercise-meta"><span>${esc(state.level)} · ${esc(labels[item.type])}</span><span>${state.index+1} / ${list.length}</span></div><div class="er-exercise-layout"><div class="er-main"><p class="er-kicker">01 · Ensaya tu respuesta</p><h2 id="er-exercise-title" lang="fr">${esc(item.title)}</h2><p class="er-instruction">${esc(item.instructionES)}</p>${item.contextFR?`<div class="er-context">${paragraphs(item.contextFR)}</div>`:''}<div class="er-prompt">${paragraphs(item.promptFR)}</div>${givenMaterial(item)}<label class="er-answer-label" for="er-draft">${item.selfAssess?'Tu texto':'Tu respuesta antes de ver la solución'}</label><textarea id="er-draft" data-exam-review-input="draft" rows="${item.selfAssess?6:3}" lang="fr" spellcheck="false" placeholder="Écris ici…">${esc(a.draft)}</textarea>${item.selfAssess?`<p class="er-word-count">${a.draft.trim()?a.draft.trim().split(/\s+/).length:0} palabras · texto libre con autoevaluación</p>`:''}<div class="er-actions">${btn('solution','Ver solución y practicar',`aria-expanded="${a.open}" aria-controls="er-solution"`)}${!item.selfAssess?btn('check','Comparar mi respuesta sin abrir el modelo','','er-text-button'):''}</div>${a.feedback?`<p class="er-feedback" role="status">${esc(a.feedback)}</p>`:''}</div>${vocabulary(item)}</div>${solution(item,a)}<footer class="er-exercise-footer"><div class="er-navigation">${btn('previous','← Anterior',`${state.index===0?'disabled':''}`,'er-button er-secondary')}${btn('next',state.index===list.length-1?'Volver al primero →':'Siguiente →','','er-button er-secondary')}</div><details class="er-sources"><summary>Objetivo y fuentes</summary><p>${esc(item.examSkill)}</p><p>${esc(item.levelBasis)}</p>${sourceLinks(item)}<p class="er-source-count">Vinculado a ${item.sourceIds.length} fichas de tu biblioteca; ejercicios redactados para este atelier.</p></details></footer></section>`:'<div class="er-empty"><h2>No hay ejercicios para esta selección</h2><p>Elige otro tipo de repaso.</p></div>'}<p class="er-bottom-note">Las respuestas se conservan durante esta sesión. Tus progresos y tarjetas anteriores siguen guardándose como hasta ahora.</p></div>`;
  }
  function matches(item,value) {const key=norm(value);if(item.type==='choice'&&/^[a-z]$/.test(key))value=item.options?.[key.charCodeAt(0)-97]||value;return(item.answers||[]).some(a=>norm(a)===norm(value));}
  function emitExamMistake(item, userAnswer, reason='wrong') {
    if (!item || item.selfAssess) return;
    callbacks.onMistake?.({
      id: `exam:${item.id}`,
      kind: 'exam-review',
      title: `${item.title} (${item.level})`,
      subtitle: `${item.instructionES || ''} · Repaso DELF/DALF`,
      detail: item.modelFR || (item.answers || [])[0] || '',
      explanation: item.explanationES || '',
      userAnswer: String(userAnswer || '').trim(),
      level: item.level,
      reason
    });
  }
  function feedback(item,value) { if(!String(value||'').trim())return 'Escribe o reconstruye una respuesta antes de compararla.';const ok=matches(item,value);if(!ok)emitExamMistake(item,value,'wrong');return ok?'Tu respuesta coincide con uno de los modelos. Comprueba también el sentido y explica el patrón en voz alta.':item.type==='cloze'?'Aún no coincide con la forma prevista. Revisa el sujeto, la terminación y los acentos; abre la explicación cuando quieras comprobar el patrón.':item.type==='choice'?'Esta elección no corresponde a la interpretación buscada. Revisa el contexto y la explicación.':'No coincide con los modelos previstos. Puede haber otras formulaciones válidas: compara el sentido y la construcción con la explicación.'; }
  function handle(action,node) {const item=current();if(!item)return false;const a=attempt(item),index=Number(node?.dataset?.index);
    if(action==='solution'){if(!a.draft.trim()){a.open=false;a.feedback='Escribe primero un intento de respuesta. No tiene que ser correcto para poder consultar la explicación.';refresh('er-draft');return true;}if(!item.selfAssess&&!matches(item,a.draft))emitExamMistake(item,a.draft,'hint');a.open=true;refresh();if(typeof document!=='undefined')document.getElementById('er-solution')?.scrollIntoView({behavior:'smooth',block:'nearest'});return true;}
    if(action==='hide-solution'){a.open=false;refresh();return true;}
    if(action==='check'){if(!item.selfAssess)a.feedback=feedback(item,a.draft);refresh('er-draft');return true;}
    if(action==='another'){a.open=false;a.feedback='Recupera la forma sin mirar el modelo; puedes corregir tu respuesta.';refresh('er-draft');return true;}
    if(action==='previous'||action==='next'){state.index=action==='previous'?Math.max(0,state.index-1):(state.index+1)%Math.max(1,filtered().length);refresh();return true;}
    if(action==='choice'&&a.open&&item.type==='choice'&&Number.isInteger(index)&&item.options[index]!==undefined){a.practiceChoice=index;a.practiceFeedback='';refresh();return true;}
    if(action==='token'&&a.open&&item.type==='order'&&Number.isInteger(index)&&item.tokens[index]!==undefined&&!a.tokens.includes(index)){a.tokens.push(index);a.practiceFeedback='';refresh();return true;}
    if(action==='remove-token'&&a.open&&Number.isInteger(index)){a.tokens.splice(index,1);a.practiceFeedback='';refresh();return true;}
    if(action==='clear-tokens'&&a.open){a.tokens=[];a.practiceFeedback='';refresh();return true;}
    if(action==='practice-check'&&a.open&&!item.selfAssess){const value=item.type==='choice'?(item.options?.[a.practiceChoice]||''):item.type==='order'?a.tokens.map(i=>item.tokens[i]).join(' '):a.draft;a.practiceFeedback=feedback(item,value);refresh();return true;}
    if(action==='audio'){const v=libraryItem(node?.dataset?.sourceId);if(v?.audio)callbacks.play(v.audio);else callbacks.toast('Este ejemplo no tiene audio disponible.');return true;}
    return false;
  }
  function input(event) {if(event?.target?.dataset?.examReviewInput!=='draft')return false;const a=attempt();a.draft=String(event.target.value||'');a.feedback='';if(current()?.selfAssess&&typeof document!=='undefined'){const counter=document.querySelector('.er-word-count');if(counter)counter.textContent=`${a.draft.trim()?a.draft.trim().split(/\s+/).length:0} palabras · texto libre con autoevaluación`;}return true;}
  function change(event) {const node=event?.target,kind=node?.dataset?.examReviewFilter;if(kind==='level'&&(data().meta?.levels||[]).includes(node.value)){state.level=node.value;state.index=0;refresh();return true;}if(kind==='type'&&(node.value==='all'||labels[node.value])){state.type=node.value;state.index=0;refresh();return true;}if(kind==='rubric'){const a=attempt(),i=Number(node.dataset.index);if(node.checked&&!a.rubric.includes(i))a.rubric.push(i);if(!node.checked)a.rubric=a.rubric.filter(x=>x!==i);return true;}return false;}
  window.ATELIER_EXAM_REVIEW={configure(options){Object.assign(callbacks,options||{});},render,handle,input,change,start(){state.active=true;},leave(){state.active=false;}};
})();
